source /root/miniconda3/etc/profile.d/conda.sh && conda activate base && python3 << 'PYEOF'
import os, json, glob

base = '/root/autodl-tmp/exp001/eval_results'
dirs = sorted(glob.glob(os.path.join(base, 'Qwen2.5-*')))
for d in dirs:
    if not os.path.isdir(d):
        continue
    name = os.path.basename(d)
    ef = os.path.join(d, 'eval_results.json')
    if not os.path.isfile(ef):
        print(f'{name}\tNO_EVAL')
        continue
    try:
        data = json.load(open(ef))
        bm = data.get('benchmarks', {})
        para = data.get('paraphrased', False)
        done = os.path.isfile(os.path.join(d, '.done'))
        vals = []
        n_bench = 0
        for b in ['mmlu','gsm8k','arc_challenge','humaneval']:
            if b in bm:
                if b == 'humaneval':
                    acc = bm[b].get('pass@1', -1)
                else:
                    acc = bm[b].get('accuracy', -1)
                vals.append(f'{acc:.4f}')
                if acc >= 0:
                    n_bench += 1
            else:
                vals.append('MISS')
        print(f'{name}\tpara={int(para)}\tdone={int(done)}\tn={n_bench}\t{chr(9).join(vals)}')
    except Exception as e:
        print(f'{name}\tERROR\t{e}')
PYEOF
